/**
 * Represents a statement that can be prefixed with the !%#* symbols to change it's behaviour.
 * @category AST
 */
export interface TaggableStatement {
    /**
     * Set to true if this module instantation has been tagged with a '!' symbol.
     */
    tagRoot: boolean;
    /**
     * Set to true if this module instantation has been tagged with a '#' symbol.
     */
    tagHighlight: boolean;
    /**
     * Set to true if this module instantation has been tagged with a '%' symbol.
     */
    tagBackground: boolean;
    /**
     * Set to true if this module instantation has been tagged with a '*' symbol.
     */
    tagDisabled: boolean;
}
/**
 * @category AST
 */
export declare class ModuleInstantiationStmt extends Statement implements TaggableStatement {
    name: string;
    args: AssignmentNode[];
    /**
     * The child statement in a module instantiation chain.
     * Can be null if this is the last statement in the chain.
     */
    child: Statement | null;
    tokens: {
        name: Token;
        firstParen: Token;
        secondParen: Token;
        modifiersInOrder: Token[];
    };
    /**
     * !
     */
    tagRoot: boolean;
    /**
     * #
     */
    tagHighlight: boolean;
    /**
     * %
     */
    tagBackground: boolean;
    /**
     * *
     */
    tagDisabled: boolean;
    constructor(name: string, args: AssignmentNode[], 
    /**
     * The child statement in a module instantiation chain.
     * Can be null if this is the last statement in the chain.
     */
    child: Statement | null, tokens: {
        name: Token;
        firstParen: Token;
        secondParen: Token;
        modifiersInOrder: Token[];
    });
    accept<R>(visitor: ASTVisitor<R>): R;
}
