/**
 * IfElseStmt represents an if-else statement. elseIfs are represented as
 * additional IfElseStmt instances in the else branch (simmilar to how C works).
 * @category AST
 */
export declare class IfElseStatement extends Statement implements TaggableStatement {
    cond: Expression;
    thenBranch: Statement;
    /**
     * The else branch.
     * It can be null if there is no else branch.
     */
    elseBranch: Statement | null;
    tokens: {
        ifKeyword: Token;
        firstParen: Token;
        secondParen: Token;
        elseKeyword: Token | null;
        modifiersInOrder: Token[];
    };
    tagRoot: boolean;
    tagHighlight: boolean;
    tagBackground: boolean;
    tagDisabled: boolean;
    constructor(cond: Expression, thenBranch: Statement, 
    /**
     * The else branch.
     * It can be null if there is no else branch.
     */
    elseBranch: Statement | null, tokens: {
        ifKeyword: Token;
        firstParen: Token;
        secondParen: Token;
        elseKeyword: Token | null;
        modifiersInOrder: Token[];
    });
    accept<R>(visitor: ASTVisitor<R>): R;
}
